IF bEnableOut17 THEN
  IF bTriggerOut17 THEN
    IF RTriggerUserDefineIoOut17.Q THEN
      g_boUserDefineIoOut17 :=TRUE;
    END_IF;  
     UserDefineIoOuttimer17(IN:=TRUE,PT:=T#500ms);
