        bEnableOut17:=FALSE;
     END_IF;      
  ELSE      
     g_boUserDefineIoOut17 :=TRUE;
  END_IF;  
ELSE
  UserDefineIoOuttimer17(IN:=FALSE);
 g_boUserDefineIoOut17 := FALSE;  
END_IF; 

