(*第1个用户自定义io输出
状态机10:M代码触发自定义输出 并判断是否等待板卡输入信号到位后输出
状态机50:手动输出自定义输出
状态机30:M代码触发自定义输出关闭 并判断是否等待板卡输入信号到位后关闭输出
状态机60:手动触发自定义输出关闭*)(*目前不能相互控制*)
RTriggerUserDefineIoOut1(CLK:= (bEnableOut1  OR g_bDefineOutputEnableOut1M));
RTriggerUserDefineIoOutOFF1(CLK:= (g_bDefineOutputEnableOutOFF1M));


IF RTriggerUserDefineIoOut1.Q THEN
  IF bEnableOut1 THEN
      UserDefineIoOuttimer1(IN:=FALSE);
      nUserDefineState1:=50;
  ELSE
    nUserDefineState1:=10;
  END_IF;
  g_bDefineOutputEnableOut1:=FALSE;
  g_bDefineOutputEnableOutOFF1:=FALSE;
  g_bDefineOutputEnableOut1M:=FALSE;
END_IF;  


IF RTriggerUserDefineIoOutOFF1.Q THEN
  nUserDefineState1:=30;
  g_bDefineOutputEnableOutOFF1:=FALSE;
  g_bDefineOutputEnableOut1:=FALSE;
  g_bDefineOutputEnableOutOFF1M:=FALSE;
END_IF;   


CASE nUserDefineState1 OF
  0:(*准备状态*)
    nUserDefineState1:=0;
  10:(*m代码控制开启*)
    IF g_dUserDefineIoOut1WaitBoardInputSignalM = 0.0 THEN
      nUserDefineState1 := 15;
    ELSE
      nUserDefineState1 := 20;
    END_IF; 
  15:
    bUserDefineIoOut1 :=TRUE;
    g_boUserDefineIoOut1 :=TRUE;
    M.ENABLE[204] := 0;
    nUserDefineState1:=0;
  20:  
    nUserDefineIoOutIndex :=LREAL_TO_INT(g_dUserDefineIoOut1WaitSignalM) - 1;
    IF g_dUserDefineIoOut1WaitBoardInputSignalM = 1.0 THEN
      IF BoardInPutArray.BoolArr[nUserDefineIoOutIndex] THEN
        nUserDefineState1 := 15;
      ELSE
        M.ENABLE[204] := 0;
        nUserDefineState1 := 0;    
      END_IF;
    ELSIF g_dUserDefineIoOut1WaitBoardInputSignalM = 2.0 THEN
      IF BoardInPutArray.BoolArr[nUserDefineIoOutIndex + 24] THEN
        nUserDefineState1 := 15;
      ELSE
        M.ENABLE[204] := 0;
        nUserDefineState1 := 0;    
      END_IF;
    ELSIF g_dUserDefineIoOut1WaitBoardInputSignalM = 3.0 THEN
      IF BoardInPutArray.BoolArr[nUserDefineIoOutIndex + 48] THEN
        nUserDefineState1 := 15;
      ELSE
        M.ENABLE[204] := 0;
        nUserDefineState1 := 0;    
      END_IF;
    END_IF;  
  30:(*m代码控制关闭*)
    IF g_dUserDefineIoOut1WaitBoardInputSignalM = 0.0 THEN
      nUserDefineState1 := 35;
    ELSE
      nUserDefineState1 := 40;
    END_IF; 
  35:  
    bUserDefineIoOut1 :=FALSE;
    g_boUserDefineIoOut1 :=FALSE;
    M.ENABLE[204] := 0;
    nUserDefineState1:=0;
  40:
    nUserDefineIoOutIndex :=LREAL_TO_INT(g_dUserDefineIoOut1WaitSignalM) - 1;
    IF g_dUserDefineIoOut1WaitBoardInputSignalM = 1.0 THEN
      IF BoardInPutArray.BoolArr[nUserDefineIoOutIndex] THEN
        nUserDefineState1 := 35;
      ELSE
        M.ENABLE[204] := 0;
        nUserDefineState1 := 0;    
      END_IF;
    ELSIF g_dUserDefineIoOut1WaitBoardInputSignalM = 2.0 THEN
      IF BoardInPutArray.BoolArr[nUserDefineIoOutIndex + 24] THEN
        nUserDefineState1 := 35;
      ELSE
        M.ENABLE[204] := 0;
        nUserDefineState1 := 0;    
      END_IF;
    ELSIF g_dUserDefineIoOut1WaitBoardInputSignalM = 3.0 THEN
      IF BoardInPutArray.BoolArr[nUserDefineIoOutIndex + 48] THEN
        nUserDefineState1 := 35;
      ELSE
        M.ENABLE[204] := 0;
        nUserDefineState1 := 0;    
      END_IF;
    END_IF;  
  50:(*手动控制开启*)
    IF bTriggerOut1 THEN
      bUserDefineIoOut1 :=TRUE; 
      g_boUserDefineIoOut1 :=TRUE;
        UserDefineIoOuttimer1(IN:=TRUE,PT:=T#500ms);
        IF UserDefineIoOuttimer1.Q THEN
          IF NOT bEnableOut1 THEN
            UserDefineIoOuttimer1(IN:=FALSE);
            bUserDefineIoOut1 :=FALSE;
            g_boUserDefineIoOut1 :=FALSE;
            nUserDefineState1:=0; 
          END_IF;   
        END_IF; 
    ELSE      
     bUserDefineIoOut1 :=bEnableOut1;
     g_boUserDefineIoOut1 :=bEnableOut1;
    END_IF;  
END_CASE;

